import { useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import { useTranslation } from "react-i18next";
import {
  ArrowLeft,
  Banknote,
  Check,
  ChevronRight,
  Clock3,
  CreditCard,
  MapPin,
  Plus,
  ShieldCheck,
  ShoppingBag,
  Truck
} from "lucide-react";
import { deliverySlots, formatUZS, getProduct } from "../data/mock";
import { cartDetails, useShop } from "../lib/store";
import { EmptyState, cn } from "../lib/ui";
import { BackButton } from "../components/BackButton";
export const Checkout = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { cart, addresses, user, promo, addAddress, placeOrder, pushToast } = useShop();
  const { subtotal, discount, delivery, total } = cartDetails(cart, promo);
  const defaultAddr = addresses.find((a) => a.isDefault) ?? addresses[0];
  const [name, setName] = useState(user?.name ?? "");
  const [phone, setPhone] = useState(user?.phone ?? "");
  const [selectedAddress, setSelectedAddress] = useState(defaultAddr?.id ?? "");
  const [slot, setSlot] = useState(deliverySlots[2]);
  const [payment, setPayment] = useState("cash");
  const [cardMethod, setCardMethod] = useState("Payme");
  const [note, setNote] = useState("");
  const [terms, setTerms] = useState(true);
  const [newAddressOpen, setNewAddressOpen] = useState(false);
  const [newLabel, setNewLabel] = useState("Uy");
  const [newAddress, setNewAddress] = useState("");
  const [newDetails, setNewDetails] = useState("");
  const [errors, setErrors] = useState({});
  if (cart.length === 0) {
    return <div className="container-page py-16">
        <EmptyState
      icon={<ShoppingBag size={30} />}
      title={t("emptyCartTitle")}
      description={t("emptyCartDesc")}
      action={<Link to="/catalog" className="btn-primary btn-sm">{t("emptyCartBtn")}</Link>}
    />
      </div>;
  }
  const chosenAddress = addresses.find((a) => a.id === selectedAddress);
  const saveNewAddress = () => {
    if (!newAddress.trim()) {
      pushToast("Manzilni kiriting", "error");
      return;
    }
    addAddress({ label: newLabel || "Uy", address: newAddress, details: newDetails, isDefault: addresses.length === 0 });
    setNewAddress("");
    setNewDetails("");
    setNewAddressOpen(false);
  };
  const submit = (e) => {
    e.preventDefault();
    const errs = {};
    if (!name.trim()) errs.name = "Ismingizni kiriting";
    if (phone.replace(/\D/g, "").length < 9) errs.phone = "Telefon raqamni kiriting";
    if (!chosenAddress) errs.address = "Manzilni tanlang";
    if (!terms) errs.terms = "Shartlarga rozilik bering";
    setErrors(errs);
    if (Object.keys(errs).length > 0) {
      pushToast("Ma'lumotlarni to'ldiring", "error");
      return;
    }
    const id = placeOrder({
      address: `${chosenAddress?.address}${chosenAddress?.details ? `, ${chosenAddress.details}` : ""}`,
      payment: payment === "cash" ? t("cash") : cardMethod,
      slot,
      note
    });
    pushToast(t("orderPlaced"), "success");
    navigate(`/order-success/${id}`);
  };
  return <div className="container-page py-5 sm:py-7">
      <div className="mb-4">
        <BackButton to="/cart" />
      </div>

      <div className="mb-5 flex flex-wrap items-end justify-between gap-3">
        <div>
          <h1 className="font-display text-2xl font-extrabold sm:text-3xl">{t("checkoutTitle")}</h1>
          <p className="mt-1 text-xs text-[var(--muted)]">{t("checkoutSubtitle")}</p>
        </div>
        <div className="flex items-center gap-1.5 text-[10px] font-extrabold text-[var(--muted)]">
          <span className="flex items-center gap-1 rounded-full bg-brand-500/10 px-2.5 py-1 text-brand-600 dark:text-brand-400"><Check size={11} /> {t("cart")}</span>
          <ChevronRight size={12} />
          <span className="flex items-center gap-1 rounded-full bg-brand-600 px-2.5 py-1 text-white">2. {t("address")}</span>
          <ChevronRight size={12} />
          <span className="flex items-center gap-1 rounded-full bg-[var(--surface-2)] px-2.5 py-1">3. {t("paymentTitle")}</span>
        </div>
      </div>

      <form onSubmit={submit} className="grid gap-5 lg:grid-cols-[1fr_360px]">
        <div className="space-y-4">
          <div className="card p-4 sm:p-5">
            <h2 className="flex items-center gap-2 font-display text-base font-extrabold"><span className="flex h-7 w-7 items-center justify-center rounded-full bg-brand-500/10 text-xs text-brand-600 dark:text-brand-400">1</span> {t("contactInfo")}</h2>
            <div className="mt-3 grid gap-3 sm:grid-cols-2">
              <div>
                <label className="label">{t("fullName")}</label>
                <input value={name} onChange={(e) => setName(e.target.value)} className={cn("input", errors.name && "border-rose-400")} placeholder="Aziz Karimov" />
                {errors.name && <p className="mt-1 text-[10px] font-bold text-rose-500">{errors.name}</p>}
              </div>
              <div>
                <label className="label">{t("phone")}</label>
                <input value={phone} onChange={(e) => setPhone(e.target.value)} className={cn("input", errors.phone && "border-rose-400")} placeholder="+998 90 123 45 67" />
                {errors.phone && <p className="mt-1 text-[10px] font-bold text-rose-500">{errors.phone}</p>}
              </div>
            </div>
          </div>

          <div className="card p-4 sm:p-5">
            <div className="flex items-center justify-between">
              <h2 className="flex items-center gap-2 font-display text-base font-extrabold"><span className="flex h-7 w-7 items-center justify-center rounded-full bg-brand-500/10 text-xs text-brand-600 dark:text-brand-400">2</span> {t("deliveryAddress")}</h2>
              <button type="button" onClick={() => setNewAddressOpen((v) => !v)} className="flex items-center gap-1 text-[10px] font-extrabold text-brand-600 dark:text-brand-400"><Plus size={12} /> {t("newAddress")}</button>
            </div>
            <div className="mt-3 space-y-2">
              {addresses.map((a) => <label key={a.id} className={cn("flex cursor-pointer items-start gap-2.5 rounded-xl border p-3 transition", selectedAddress === a.id ? "border-brand-500 bg-brand-500/5" : "hover:bg-[var(--surface-2)]")}>
                  <input type="radio" name="address" checked={selectedAddress === a.id} onChange={() => setSelectedAddress(a.id)} className="mt-1 accent-brand-600" />
                  <span className="min-w-0 flex-1">
                    <span className="flex items-center gap-1.5 text-xs font-extrabold"><MapPin size={12} className="text-brand-500" /> {a.label} {a.isDefault && <span className="badge bg-brand-500/15 text-brand-700 dark:text-brand-300">Asosiy</span>}</span>
                    <span className="mt-0.5 block text-[11px] text-[var(--muted)]">{a.address}</span>
                    {a.details && <span className="block text-[10px] text-[var(--muted)]">{a.details}</span>}
                  </span>
                </label>)}
              {errors.address && <p className="text-[10px] font-bold text-rose-500">{errors.address}</p>}
            </div>

            {newAddressOpen && <div className="mt-3 rounded-xl border border-dashed p-3">
                <div className="grid gap-2 sm:grid-cols-2">
                  <input value={newLabel} onChange={(e) => setNewLabel(e.target.value)} className="input h-9 py-1 text-xs" placeholder={t("addressLabel")} />
                  <input value={newDetails} onChange={(e) => setNewDetails(e.target.value)} className="input h-9 py-1 text-xs" placeholder={t("addressDetails")} />
                </div>
                <input value={newAddress} onChange={(e) => setNewAddress(e.target.value)} className="input mt-2 h-9 py-1 text-xs" placeholder={t("address")} />
                <button type="button" onClick={saveNewAddress} className="btn-primary mt-2 w-full btn-sm">{t("saveAddress")}</button>
              </div>}

            <div className="mt-4">
              <label className="label flex items-center gap-1"><Clock3 size={12} /> {t("deliverySlot")}</label>
              <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
                {deliverySlots.map((s) => <button
    key={s}
    type="button"
    onClick={() => setSlot(s)}
    className={cn("rounded-xl border px-2 py-2 text-[10px] font-bold transition", slot === s ? "border-brand-500 bg-brand-500/10 text-brand-600 dark:text-brand-400" : "text-[var(--muted)] hover:bg-[var(--surface-2)]")}
  >
                    {s}
                  </button>)}
              </div>
            </div>
          </div>

          <div className="card p-4 sm:p-5">
            <h2 className="flex items-center gap-2 font-display text-base font-extrabold"><span className="flex h-7 w-7 items-center justify-center rounded-full bg-brand-500/10 text-xs text-brand-600 dark:text-brand-400">3</span> {t("paymentTitle")}</h2>
            <div className="mt-3 grid gap-2 sm:grid-cols-2">
              <label className={cn("flex cursor-pointer items-start gap-2.5 rounded-xl border p-3 transition", payment === "cash" ? "border-brand-500 bg-brand-500/5" : "hover:bg-[var(--surface-2)]")}>
                <input type="radio" name="payment" checked={payment === "cash"} onChange={() => setPayment("cash")} className="mt-1 accent-brand-600" />
                <span>
                  <span className="flex items-center gap-1.5 text-xs font-extrabold"><Banknote size={14} className="text-brand-500" /> {t("cash")}</span>
                  <span className="mt-0.5 block text-[10px] text-[var(--muted)]">{t("paymentCashDesc")}</span>
                </span>
              </label>
              <label className={cn("flex cursor-pointer items-start gap-2.5 rounded-xl border p-3 transition", payment === "card" ? "border-brand-500 bg-brand-500/5" : "hover:bg-[var(--surface-2)]")}>
                <input type="radio" name="payment" checked={payment === "card"} onChange={() => setPayment("card")} className="mt-1 accent-brand-600" />
                <span>
                  <span className="flex items-center gap-1.5 text-xs font-extrabold"><CreditCard size={14} className="text-brand-500" /> {t("card")}</span>
                  <span className="mt-0.5 block text-[10px] text-[var(--muted)]">{t("paymentCardDesc")}</span>
                </span>
              </label>
            </div>
            {payment === "card" && <div className="mt-2 grid grid-cols-3 gap-2">
                {["Payme", "Click", "Uzum Bank"].map((m) => <button key={m} type="button" onClick={() => setCardMethod(m)} className={cn("rounded-xl border px-2 py-2 text-[10px] font-extrabold transition", cardMethod === m ? "border-brand-500 bg-brand-500/10 text-brand-600 dark:text-brand-400" : "text-[var(--muted)]")}>{m}</button>)}
              </div>}
            <div className="mt-4">
              <label className="label">{t("orderComment")}</label>
              <textarea value={note} onChange={(e) => setNote(e.target.value)} rows={2} className="input resize-none" placeholder={t("notePlaceholder")} />
            </div>
            <label className="mt-3 flex items-start gap-2 text-[10px] font-semibold text-[var(--muted)]">
              <input type="checkbox" checked={terms} onChange={(e) => setTerms(e.target.checked)} className="mt-0.5 accent-brand-600" />
              <span>{t("termsAgree")}</span>
            </label>
            {errors.terms && <p className="mt-1 text-[10px] font-bold text-rose-500">{errors.terms}</p>}
          </div>
        </div>

        <div className="h-fit space-y-3 lg:sticky lg:top-32">
          <div className="card p-4 sm:p-5">
            <h2 className="font-display text-lg font-extrabold">{t("yourOrder")}</h2>
            <div className="mt-3 max-h-56 space-y-2 overflow-y-auto pr-1">
              {cart.map((item) => {
    const p = getProduct(item.productId);
    if (!p) return null;
    return <div key={item.productId} className="flex items-center gap-2">
                    <span className={cn("flex h-9 w-9 shrink-0 items-center justify-center overflow-hidden rounded-lg bg-gradient-to-br text-lg", p.gradient)}>
                      {p.img ? <img alt={p.name} className="h-full w-full object-contain p-0.5" src={p.img} /> : p.emoji}
                    </span>
                    <div className="min-w-0 flex-1">
                      <p className="truncate text-[11px] font-extrabold">{p.name}</p>
                      <p className="text-[9px] text-[var(--muted)]">{item.qty} × {formatUZS(p.price)}</p>
                    </div>
                    <p className="text-[10px] font-extrabold">{formatUZS(p.price * item.qty)}</p>
                  </div>;
  })}
            </div>

            <div className="mt-3 space-y-2 border-t pt-3 text-[11px]">
              <div className="flex justify-between"><span className="text-[var(--muted)]">{t("subtotal")}</span><b>{formatUZS(subtotal)}</b></div>
              {discount > 0 && <div className="flex justify-between text-brand-600 dark:text-brand-400"><span>{t("discount")}</span><b>−{formatUZS(discount)}</b></div>}
              <div className="flex justify-between"><span className="text-[var(--muted)]">{t("deliveryFee")}</span><b className={delivery === 0 ? "text-brand-600 dark:text-brand-400" : ""}>{delivery === 0 ? t("freeDelivery") : formatUZS(delivery)}</b></div>
              <div className="flex items-end justify-between border-t pt-2.5">
                <span className="text-xs font-extrabold">{t("total")}</span>
                <span className="font-display text-xl font-extrabold text-brand-700 dark:text-brand-400">{formatUZS(total)}</span>
              </div>
            </div>

            <button type="submit" className="btn-primary mt-4 w-full"><Truck size={16} /> {t("confirmOrder")}</button>
            <p className="mt-2 flex items-center justify-center gap-1 text-[9px] font-bold text-[var(--muted)]"><ShieldCheck size={11} /> {t("securePayment")}</p>
          </div>

          <div className="rounded-2xl border border-dashed p-3 text-[10px] leading-relaxed text-[var(--muted)]">
            {chosenAddress ? `\u{1F4CD} ${chosenAddress.address}${chosenAddress.details ? `, ${chosenAddress.details}` : ""}` : "\u{1F4CD} Manzil tanlanmagan"}
            <br />🕒 {slot} · {payment === "cash" ? t("cash") : cardMethod}
          </div>
        </div>
      </form>
    </div>;
};
